// seriesID mints the deterministic series id from (libraryID, relativePath):
// ser_<libraryID>_<sha16hex16(relative_path)> (serials-library design.md
// §Interfaces §5 — the first 16 lowercase hex chars of sha256 over the raw
// relative-path bytes). It is single-sourced HERE so every consumer (scan, the
// API layer, the enrich queue) reads ids from rows and never re-derives them.
func seriesID(libraryID int64, relativePath string) string {
	sum := sha256.Sum256([]byte(relativePath))
	return fmt.Sprintf("ser_%d_%s", libraryID, hex.EncodeToString(sum[:])[:16])
}

// PutSeries upserts a series keyed by (library_id, relative_path).
// Re-scanning a serial library yields exactly one row per directory: on
// conflict the row's id and created_at are preserved (so series references and
// enrichment history survive) and the mutable fields are refreshed with
// updated_at advanced. The id is minted here from (library_id, relative_path)
// — the ID field of the argument is not consulted — so a caller can never
// persist a mismatched identity. Status is persisted as given (scan owns the
// lifecycle decision; the store stays value-agnostic, mirroring PutItem).
